-- ═══════════════════════════════════════════════════════════════════════════
-- Amryn™ AIGrowthIntelligence® Software
-- Migration 06 — Permission catalogue, role matrix, triggers
-- ═══════════════════════════════════════════════════════════════════════════

-- Migration 04 applies `force row level security` to all 45 tables, and these
-- two carry a select policy and nothing else. FORCE is the part that matters:
-- ordinary RLS exempts a table's owner, FORCE does not, so these seed inserts
-- are refused for anyone lacking BYPASSRLS — including whoever is applying the
-- migration.
--
--   ERROR: new row violates row-level security policy for table "permissions"
--
-- Superusers bypass RLS unconditionally, so a local PostgreSQL never showed
-- it. Whether a hosted project does depends on whether its role happens to
-- carry BYPASSRLS, which is not a thing to build a schema on.
--
-- FORCE is lifted for the length of the seed and restored immediately. Both
-- statements are inside the migration's transaction, so there is no window in
-- which the tables are deployed unprotected.
--
-- These two are a fixed catalogue, not tenant data: every organisation reads
-- the same rows, which is why a select policy is all they ever needed.
alter table public.permissions      no force row level security;
alter table public.role_permissions no force row level security;

insert into public.permissions (key, category, description) values
  ('view_performance',        'Performance',    'View business performance dashboards and metrics'),
  ('view_financial_data',     'Performance',    'View revenue, cost, margin and cash figures'),
  ('view_sales_data',         'Performance',    'View sales records, customers and pipeline value'),
  ('view_operations_data',    'Performance',    'View operational measures such as delivery and utilisation'),
  ('view_intelligence',       'Intelligence',   'View AI DigitalTwin® findings, events and insights'),
  ('view_market_intelligence','Intelligence',   'View external market signals'),
  ('view_competitors',        'Intelligence',   'View tracked competitors and their activity'),
  ('view_opportunities',      'Opportunities',  'View the opportunity pipeline and radar'),
  ('assign_opportunities',    'Opportunities',  'Assign opportunities to colleagues'),
  ('manage_opportunities',    'Opportunities',  'Create, edit and progress opportunities'),
  ('view_recommendations',    'Strategy',       'View AI recommendations'),
  ('manage_recommendations',  'Strategy',       'Accept, dismiss and progress recommendations'),
  ('view_goals',              'Strategy',       'View goals and strategic initiatives'),
  ('manage_goals',            'Strategy',       'Create and edit goals and initiatives'),
  ('view_risks',              'Risk',           'View the risk register and risk dashboard'),
  ('manage_risks',            'Risk',           'Raise, reassess and close risks'),
  ('view_alerts',             'Risk',           'View alerts'),
  ('manage_alerts',           'Risk',           'Acknowledge, assign, snooze and dismiss alerts'),
  ('view_data_sources',       'Data',           'View connected sources, imports and data health'),
  ('import_data',             'Data',           'Upload and import business data'),
  ('manage_integrations',     'Data',           'Create and configure data connections'),
  ('manage_metrics',          'Data',           'Define metrics and health-score weighting'),
  ('manage_competitors',      'Intelligence',   'Add and edit tracked competitors'),
  ('manage_radar',            'Intelligence',   'Configure market sources and radar scoring'),
  ('generate_reports',        'Reporting',      'Generate and export reports'),
  ('use_ai_assistant',        'Intelligence',   'Ask the Amryn AI Assistant questions'),
  ('view_audit_log',          'Administration', 'Read the organisation audit trail'),
  ('manage_users',            'Administration', 'Invite, edit and remove members and permissions'),
  ('manage_organisation',     'Administration', 'Edit the organisation, regions, branches and departments'),
  ('manage_billing',          'Administration', 'View and change the subscription and billing details');

-- ── role matrix ───────────────────────────────────────────────────────────
-- Reach widens down the list; scope (which branches a member sees) is a
-- separate axis, applied by RLS on top of these grants.

do $$
declare
  everything text[] := array(select key from public.permissions order by key);

  viewer text[] := array[
    'view_performance','view_intelligence','view_market_intelligence','view_competitors',
    'view_opportunities','view_recommendations','view_goals','view_alerts','use_ai_assistant'
  ];

  department_manager text[] := viewer || array[
    'view_sales_data','view_operations_data','view_risks','view_data_sources',
    'manage_goals','manage_alerts','generate_reports'
  ];

  branch_manager text[] := department_manager || array[
    'view_financial_data','manage_opportunities','manage_recommendations','manage_risks','import_data'
  ];

  regional_manager text[] := branch_manager || array[
    'assign_opportunities','view_audit_log'
  ];

  analyst text[] := array[
    'view_performance','view_financial_data','view_sales_data','view_operations_data',
    'view_intelligence','view_market_intelligence','view_competitors','view_opportunities',
    'view_recommendations','view_goals','view_risks','view_alerts','view_data_sources',
    'import_data','manage_metrics','generate_reports','use_ai_assistant'
  ];

  -- The executive view is the whole business, minus the plumbing that
  -- administrators and analysts own.
  executive text[] := regional_manager || array[
    'manage_competitors','manage_radar','manage_users'
  ];
begin
  insert into public.role_permissions (role, permission_key)
  select 'super_admin'::public.org_role, unnest(everything)
  union all select 'org_admin', unnest(everything)
  union all select 'executive', unnest(executive)
  union all select 'regional_manager', unnest(regional_manager)
  union all select 'branch_manager', unnest(branch_manager)
  union all select 'department_manager', unnest(department_manager)
  union all select 'analyst', unnest(analyst)
  union all select 'viewer', unnest(viewer)
  on conflict do nothing;
end;
$$;

-- Protection restored before anything else runs.
alter table public.permissions      force row level security;
alter table public.role_permissions force row level security;

-- ═══════════════════════════════════════════════════════════════════════════
-- Triggers
-- ═══════════════════════════════════════════════════════════════════════════

create or replace function amryn.touch_updated_at()
returns trigger
language plpgsql
as $$
begin
  new.updated_at := now();
  return new;
end;
$$;

do $$
declare
  t text;
begin
  foreach t in array array[
    'organisations','user_profiles','regions','branches','departments',
    'organisation_members','subscriptions','data_sources','data_connections',
    'business_metrics','competitors','opportunities','goals',
    'strategic_initiatives','ai_recommendations','risks','ai_conversations'
  ]
  loop
    execute format(
      'create trigger %I before update on public.%I for each row execute function amryn.touch_updated_at()',
      t || '_touch', t
    );
  end loop;
end;
$$;

-- Mirror new auth users into user_profiles so the app always has a profile to
-- render, without a first-login write path that could fail.
create or replace function amryn.handle_new_user()
returns trigger
language plpgsql
security definer
set search_path = public, pg_temp
as $$
begin
  insert into public.user_profiles (id, email, full_name, avatar_url)
  values (
    new.id,
    new.email,
    coalesce(new.raw_user_meta_data ->> 'full_name', new.raw_user_meta_data ->> 'name'),
    new.raw_user_meta_data ->> 'avatar_url'
  )
  on conflict (id) do update
    set email = excluded.email,
        full_name = coalesce(public.user_profiles.full_name, excluded.full_name);
  return new;
end;
$$;

-- Guarded, because creating a trigger requires owning the table and on a
-- hosted Supabase project auth.users belongs to supabase_auth_admin rather
-- than the role applying this file. Unguarded, this one statement failed the
-- entire migration — taking the permission catalogue, the role matrix and
-- create_organisation down with it, and leaving a database that looked like
-- the migrations had never run.
--
-- Where the trigger cannot be installed, public.ensure_user_profile() in
-- migration 10 does the same work on first sign-in instead.
do $$
begin
  create trigger on_auth_user_created
    after insert on auth.users
    for each row execute function amryn.handle_new_user();
exception
  when insufficient_privilege then
    raise notice 'not permitted to add a trigger to auth.users; profiles are created on first sign-in instead';
  when duplicate_object then
    raise notice 'profile trigger already present';
end;
$$;

-- Risk severity is derived from likelihood × impact, but stored, so that a
-- later change to the scale does not silently rewrite history.
create or replace function amryn.derive_risk_severity()
returns trigger
language plpgsql
as $$
declare
  product integer := new.likelihood * new.impact;
begin
  new.severity := case
    when product >= 20 then 'critical'::public.priority_level
    when product >= 12 then 'high'::public.priority_level
    when product >= 6  then 'medium'::public.priority_level
    else 'low'::public.priority_level
  end;
  return new;
end;
$$;

create trigger risks_derive_severity
  before insert or update of likelihood, impact on public.risks
  for each row execute function amryn.derive_risk_severity();

-- ── organisation bootstrap ────────────────────────────────────────────────
-- Creating an organisation from the app is a single call: it must also create
-- the caller's membership, the subscription and the default weighting, or none
-- of it. SECURITY DEFINER because the caller is not yet a member of the
-- organisation whose rows are being written.

create or replace function public.create_organisation(
  p_name text,
  p_slug text,
  p_industry text default null,
  p_country_code char(2) default 'ZA',
  p_currency_code char(3) default 'ZAR'
)
returns uuid
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  new_org uuid;
  uid uuid := auth.uid();
begin
  if uid is null then
    raise exception 'authentication required' using errcode = '42501';
  end if;

  insert into public.organisations (name, slug, industry, country_code, currency_code)
  values (p_name, lower(p_slug), p_industry, upper(p_country_code), upper(p_currency_code))
  returning id into new_org;

  insert into public.organisation_members (organisation_id, user_id, role, status, scope_kind)
  values (new_org, uid, 'org_admin', 'active', 'organisation');

  insert into public.subscriptions (organisation_id, plan, status, trial_ends_at)
  values (new_org, 'starter', 'trialing', now() + interval '30 days');

  insert into public.health_score_weights (organisation_id, category, weight) values
    (new_org, 'financial',   0.25),
    (new_org, 'operational', 0.20),
    (new_org, 'sales',       0.20),
    (new_org, 'growth',      0.15),
    (new_org, 'customer',    0.10),
    (new_org, 'strategic',   0.10);

  insert into public.opportunity_score_weights (organisation_id) values (new_org);

  insert into public.audit_logs (organisation_id, actor_id, action, entity_type, entity_id, summary)
  values (new_org, uid, 'organisation.created', 'organisation', new_org::text, p_name);

  return new_org;
end;
$$;

revoke all on function public.create_organisation(text, text, text, char, char) from public, anon;
grant execute on function public.create_organisation(text, text, text, char, char) to authenticated;

-- Health-score weights must sum to 1 for the score to be a true weighted mean.
create or replace function amryn.assert_health_weights_sum()
returns trigger
language plpgsql
as $$
declare
  total numeric;
  org uuid := coalesce(new.organisation_id, old.organisation_id);
begin
  select sum(weight) into total
    from public.health_score_weights
   where organisation_id = org;

  if total is not null and abs(total - 1) > 0.001 then
    raise exception 'health score weights for organisation % sum to %, expected 1', org, total;
  end if;
  return null;
end;
$$;

create constraint trigger health_weights_sum_to_one
  after insert or update or delete on public.health_score_weights
  deferrable initially deferred
  for each row execute function amryn.assert_health_weights_sum();

-- PostgREST answers from a cached copy of the schema and is not told by
-- applying SQL. Without this, everything above exists and stays invisible to
-- the application — which reads exactly like a migration that never ran.
notify pgrst, 'reload schema';

-- ══════════════════════════════════════════════════════════════════════
-- 20260830080000_07_sector_policy.sql
-- ══════════════════════════════════════════════════════════════════════
do $setup$ begin raise notice 'applying 20260830080000_07_sector_policy.sql'; end $setup$;

-- ═══════════════════════════════════════════════════════════════════════════
-- Amryn™ AIGrowthIntelligence® Software
-- Migration 07 — Sector policy belongs to the customer, not to the platform
--
-- Migration 03 defaulted market scanning to the private sector alone and the
-- recommendation layer refused to surface tenders at all. That conflated two
-- different things:
--
--   · Amryn's own commercial posture — the company does not take on
--     government-sector business. That is a fact about who Amryn sells to,
--     and it belongs in the company's positioning, not in a WHERE clause.
--
--   · What an Amryn customer should be shown. Customers are private
--     businesses, and a municipal supply tender is ordinary revenue to a
--     wholesaler. Filtering it out withheld real money from the people
--     paying for the product.
--
-- So sector scope becomes an explicit, per-organisation setting. The default
-- is to surface everything and let relevance and strategic alignment decide
-- what ranks — which is what those factors are for. An organisation that does
-- not pursue public-sector work narrows the setting once, and the radar
-- honours it everywhere.
-- ═══════════════════════════════════════════════════════════════════════════

-- A tender is its own kind of opportunity: a defined scope, a published
-- deadline and a competitive submission. Modelling it as 'market_expansion'
-- lost the shape that makes it actionable.
alter type public.opportunity_kind add value if not exists 'tender';

-- ── per-organisation sector scope ─────────────────────────────────────────
-- Which sectors this organisation wants its radar to surface. Defaults to all
-- of them: an opportunity is filtered out only because a customer chose to
-- filter it, never because the platform decided on their behalf.

alter table public.organisations
  add column if not exists sector_scope public.market_sector[]
    not null default '{private,public,mixed,unknown}';

comment on column public.organisations.sector_scope is
  'Sectors the AI OpportunityRadar® may surface for this organisation. Set by the customer. Amryn''s own commercial posture is not encoded here.';

alter table public.organisations
  add constraint sector_scope_not_empty check (cardinality(sector_scope) > 0);

-- Existing market sources were seeded private-only by the previous default.
-- Widen them to match the new posture; a customer narrows from here.
alter table public.market_sources
  alter column sector_policy set default '{private,public,mixed,unknown}';

update public.market_sources
   set sector_policy = '{private,public,mixed,unknown}'
 where sector_policy = '{private}';

-- ── honouring the setting ─────────────────────────────────────────────────
-- Enforced in the database rather than only in the query layer, so a report,
-- an export and the assistant all see the same set. A row outside the
-- organisation's chosen scope is simply not selectable.

create or replace function amryn.sector_in_scope(p_org uuid, p_sector public.market_sector)
returns boolean
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select coalesce(
    (select p_sector = any (o.sector_scope) from public.organisations o where o.id = p_org),
    false
  );
$$;

grant execute on function amryn.sector_in_scope(uuid, public.market_sector) to authenticated;

drop policy if exists opportunities_read on public.opportunities;
create policy opportunities_read on public.opportunities
  for select to authenticated
  using (
    amryn.has_permission(organisation_id, 'view_opportunities')
    and amryn.can_see_branch(organisation_id, branch_id)
    and amryn.sector_in_scope(organisation_id, sector)
  );

drop policy if exists market_signals_read on public.market_signals;
create policy market_signals_read on public.market_signals
  for select to authenticated
  using (
    amryn.has_permission(organisation_id, 'view_market_intelligence')
    and amryn.sector_in_scope(organisation_id, sector)
  );

-- PostgREST answers from a cached copy of the schema and is not told by
-- applying SQL. Without this, everything above exists and stays invisible to
-- the application — which reads exactly like a migration that never ran.
notify pgrst, 'reload schema';

-- ══════════════════════════════════════════════════════════════════════
-- 20260830190000_08_organisation_bootstrap_rpc.sql
-- ══════════════════════════════════════════════════════════════════════
do $setup$ begin raise notice 'applying 20260830190000_08_organisation_bootstrap_rpc.sql'; end $setup$;

-- ── organisation bootstrap, made reachable ────────────────────────────────
--
-- Symptom this fixes, seen on the live deployment at /onboarding:
--
--   Could not find the function public.create_organisation(p_country_code,
--   p_currency_code, p_industry, p_name, p_slug) in the schema cache
--
-- PostgREST resolves a remote call against a cache of the schema, not against
-- the schema. Three separate things produce that one message, and the reader
-- cannot tell them apart:
--
--   1. The function is genuinely absent — migration 06 was never applied.
--   2. It exists, but PostgREST last built its cache before it did. Applying
--      migrations through the SQL editor does not reload that cache, so a
--      correct database serves a stale answer indefinitely.
--   3. It exists, but the caller's arguments cannot be coerced to its
--      parameter types, so no candidate matches.
--
-- This migration settles all three, and is safe to run whether or not 06 was.
--
-- On (3): the parameters were char(2) and char(3). A blank-padded fixed-width
-- type is a poor thing to expose over an interface that sends everything as
-- JSON text, and it buys nothing here — the columns are still char(2)/char(3)
-- with their own check constraints, so the storage guarantee is unchanged.
-- The parameters become text, and the function validates them itself so a bad
-- value is a sentence rather than a silent truncation.
--
-- A type change cannot be made with `create or replace`: Postgres treats a
-- different parameter type as a different function and would leave both in
-- place. Two candidates with identical argument names is worse than none —
-- PostgREST then fails as ambiguous. So both signatures are dropped first.

drop function if exists public.create_organisation(text, text, text, char, char);
drop function if exists public.create_organisation(text, text, text, text, text);

create function public.create_organisation(
  p_name text,
  p_slug text,
  p_industry text default null,
  p_country_code text default 'ZA',
  p_currency_code text default 'ZAR'
)
returns uuid
language plpgsql
security definer
-- SECURITY DEFINER because the caller is not yet a member of the organisation
-- whose rows are being written. search_path is pinned so the elevated body
-- cannot be redirected to a caller-controlled schema.
set search_path = public, pg_temp
as $$
declare
  new_org  uuid;
  uid      uuid := auth.uid();
  country  text := upper(btrim(coalesce(p_country_code, 'ZA')));
  currency text := upper(btrim(coalesce(p_currency_code, 'ZAR')));
begin
  if uid is null then
    raise exception 'authentication required' using errcode = '42501';
  end if;

  -- Validated here rather than left to the column cast. char(2) silently
  -- truncates anything longer, so 'ZAF' would have been stored as 'ZA' and
  -- nobody would have been told.
  if length(country) <> 2 then
    raise exception 'country code must be two letters, got %', country
      using errcode = '22023';
  end if;

  if length(currency) <> 3 then
    raise exception 'currency code must be three letters, got %', currency
      using errcode = '22023';
  end if;

  insert into public.organisations (name, slug, industry, country_code, currency_code)
  values (p_name, lower(p_slug), p_industry, country, currency)
  returning id into new_org;

  insert into public.organisation_members (organisation_id, user_id, role, status, scope_kind)
  values (new_org, uid, 'org_admin', 'active', 'organisation');

  insert into public.subscriptions (organisation_id, plan, status, trial_ends_at)
  values (new_org, 'starter', 'trialing', now() + interval '30 days');

  insert into public.health_score_weights (organisation_id, category, weight) values
    (new_org, 'financial',   0.25),
    (new_org, 'operational', 0.20),
    (new_org, 'sales',       0.20),
    (new_org, 'growth',      0.15),
    (new_org, 'customer',    0.10),
    (new_org, 'strategic',   0.10);

  insert into public.opportunity_score_weights (organisation_id) values (new_org);

  insert into public.audit_logs (organisation_id, actor_id, action, entity_type, entity_id, summary)
  values (new_org, uid, 'organisation.created', 'organisation', new_org::text, p_name);

  return new_org;
end;
$$;

-- anon must never reach this: it writes an organisation and an admin
-- membership, and it runs as its owner.
revoke all on function public.create_organisation(text, text, text, text, text) from public, anon;
grant execute on function public.create_organisation(text, text, text, text, text) to authenticated;

-- Cause (2). Without this the function above exists and stays invisible over
-- the API until something else happens to reload the cache.
notify pgrst, 'reload schema';

-- ══════════════════════════════════════════════════════════════════════
-- 20260830200000_09_default_privileges.sql
-- ══════════════════════════════════════════════════════════════════════
do $setup$ begin raise notice 'applying 20260830200000_09_default_privileges.sql'; end $setup$;

-- ── privileges for tables added later ─────────────────────────────────────
--
-- Migration 05 grants `authenticated` its table privileges with
-- `grant ... on all tables in schema public`. That phrasing is a snapshot: it
-- covers the tables existing at the moment it runs, and says nothing about any
-- added afterwards. A table created by a future migration would therefore be
-- unreachable by every signed-in user, and PostgREST would report it as
-- missing from the schema cache rather than as a privilege problem — which is
-- a long way from the cause.
--
-- Default privileges close that, so the grant applies to what does not exist
-- yet.
--
-- Deliberately nothing for `anon`. It holds no privilege on these tables and
-- should not: every one of the 45 policies targets `authenticated`, so Row
-- Level Security alone would already return an anonymous caller nothing, and
-- withholding the grant as well means a policy misconfigured tomorrow still
-- cannot leak to an anonymous request. 10_rls_isolation_test.sql asserts that
-- second wall is standing.

alter default privileges in schema public
  grant select, insert, update, delete on tables to authenticated;

alter default privileges in schema public
  grant usage, select on sequences to authenticated;

notify pgrst, 'reload schema';

-- ══════════════════════════════════════════════════════════════════════
-- 20260830210000_10_profile_without_auth_trigger.sql
-- ══════════════════════════════════════════════════════════════════════
do $setup$ begin raise notice 'applying 20260830210000_10_profile_without_auth_trigger.sql'; end $setup$;

-- ── surviving a trigger that cannot be created ────────────────────────────
--
-- Migration 06 ends with:
--
--   create trigger on_auth_user_created after insert on auth.users ...
--
-- Creating a trigger requires ownership of the table, and on a hosted Supabase
-- project auth.users belongs to supabase_auth_admin, not to the role the SQL
-- editor runs as. Whether that succeeds depends on the vintage of the project;
-- on the ones where it does not, it fails with
--
--   ERROR: 42501: must be owner of relation users
--
-- and because the editor runs each script in a transaction, the whole of
-- migration 06 rolls back — the permission catalogue, the role matrix and
-- create_organisation with it. The database is then left with every table and
-- policy in place and none of its seed data, which reads exactly like
-- migrations that were never applied.
--
-- A local PostgreSQL owns everything, so the suite never saw it.
--
-- Rather than depend on knowing which kind of project this is, the trigger
-- becomes optional and its work is made reachable another way.

-- 1. Never let this be the statement that fails a migration.
do $$
begin
  create trigger on_auth_user_created
    after insert on auth.users
    for each row execute function amryn.handle_new_user();
  raise notice 'profile trigger installed on auth.users';
exception
  when insufficient_privilege then
    raise notice 'not permitted to add a trigger to auth.users on this project; profiles are created on first sign-in instead';
  when duplicate_object then
    raise notice 'profile trigger already present';
end;
$$;

-- 2. The first-login write path the trigger existed to avoid needing.
--
-- SECURITY DEFINER so it can read auth.users, which the caller cannot. It acts
-- only on auth.uid(), so a caller can create a profile for themselves and for
-- nobody else — there is no parameter to point at another user.
create or replace function public.ensure_user_profile()
returns void
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  uid uuid := auth.uid();
begin
  if uid is null then
    return;
  end if;

  insert into public.user_profiles (id, email, full_name, avatar_url)
  select
    u.id,
    u.email,
    coalesce(u.raw_user_meta_data ->> 'full_name', u.raw_user_meta_data ->> 'name'),
    u.raw_user_meta_data ->> 'avatar_url'
  from auth.users u
  where u.id = uid
  on conflict (id) do update
    set email = excluded.email,
        full_name = coalesce(public.user_profiles.full_name, excluded.full_name);
end;
$$;

revoke all on function public.ensure_user_profile() from public, anon;
grant execute on function public.ensure_user_profile() to authenticated;

-- 3. Anyone who signed up while the trigger was absent has no profile. Backfill
-- them, so this migration repairs the accounts it was too late to prevent.
insert into public.user_profiles (id, email, full_name, avatar_url)
select
  u.id,
  u.email,
  coalesce(u.raw_user_meta_data ->> 'full_name', u.raw_user_meta_data ->> 'name'),
  u.raw_user_meta_data ->> 'avatar_url'
from auth.users u
on conflict (id) do nothing;

notify pgrst, 'reload schema';

-- ══════════════════════════════════════════════════════════════════════
-- 20260831090000_11_invitations.sql
-- ══════════════════════════════════════════════════════════════════════
do $setup$ begin raise notice 'applying 20260831090000_11_invitations.sql'; end $setup$;

-- ═══════════════════════════════════════════════════════════════════════════
-- Amryn™ AIGrowthIntelligence® Software
-- Migration 11 — Invitations
-- ═══════════════════════════════════════════════════════════════════════════
--
-- Until now every person who signed up got an organisation of their own, and
-- there was no way into anyone else's. The members screen already rendered an
-- `invited` status and nothing ever wrote one.
--
-- The obvious implementation does not work: organisation_members.user_id
-- references auth.users and is not null, so a membership cannot exist for
-- somebody who has not signed up yet — which is exactly who an invitation is
-- for. So an invitation is its own record, and becomes a membership when it is
-- accepted.
--
-- The link is the credential, so it is treated as one. Only a SHA-256 hash of
-- the token is stored: the database never holds anything that grants access,
-- and a leaked backup does not let anyone in. The raw token exists once, in the
-- response that creates it, and is shown to the person who will send it on.

create table public.organisation_invitations (
  id              uuid primary key default gen_random_uuid(),
  organisation_id uuid not null references public.organisations (id) on delete cascade,
  -- citext, so an invitation to Someone@Example.com is accepted by
  -- someone@example.com. Case-sensitivity here would be a support burden and
  -- protects nothing.
  email           citext not null,
  role            public.org_role not null default 'viewer',
  scope_kind      public.scope_kind not null default 'organisation',
  scope_ids       uuid[] not null default '{}',
  -- Never the token itself.
  token_hash      text not null unique,
  invited_by      uuid references auth.users (id) on delete set null,
  expires_at      timestamptz not null default now() + interval '14 days',
  accepted_at     timestamptz,
  accepted_by     uuid references auth.users (id) on delete set null,
  revoked_at      timestamptz,
  created_at      timestamptz not null default now(),
  updated_at      timestamptz not null default now(),

  constraint scope_ids_match_kind check (
    (scope_kind = 'organisation' and cardinality(scope_ids) = 0)
    or (scope_kind <> 'organisation' and cardinality(scope_ids) > 0)
  ),
  -- An invitation is either open, accepted or revoked. Recording both an
  -- acceptance and a revocation would leave no answer to "did they get in".
  constraint not_both_accepted_and_revoked check (
    accepted_at is null or revoked_at is null
  )
);

-- One open invitation per address per organisation. A partial index rather than
-- a plain unique constraint, so the same person can be re-invited after an
-- invitation is revoked or expires.
create unique index organisation_invitations_open_email
  on public.organisation_invitations (organisation_id, email)
  where accepted_at is null and revoked_at is null;

create index organisation_invitations_org on public.organisation_invitations (organisation_id);

create trigger organisation_invitations_touch
  before update on public.organisation_invitations
  for each row execute function amryn.touch_updated_at();

-- ── who may see and write them ────────────────────────────────────────────
alter table public.organisation_invitations enable row level security;
alter table public.organisation_invitations force row level security;

-- Reading an invitation reveals who is being brought into the business, so it
-- is limited to the people who manage members — not every colleague.
create policy organisation_invitations_read on public.organisation_invitations
  for select to authenticated
  using (amryn.has_permission(organisation_id, 'manage_users'));

create policy organisation_invitations_write on public.organisation_invitations
  for insert to authenticated
  with check (amryn.has_permission(organisation_id, 'manage_users'));

-- Update covers revoking. Acceptance does not come through here: the invitee
-- is not a member yet and no policy would let them touch the row, which is why
-- accept_invitation() runs as its owner.
create policy organisation_invitations_update on public.organisation_invitations
  for update to authenticated
  using (amryn.has_permission(organisation_id, 'manage_users'))
  with check (amryn.has_permission(organisation_id, 'manage_users'));

grant select, insert, update on public.organisation_invitations to authenticated;

-- ── looking at an invitation before accepting it ──────────────────────────
--
-- The invitee cannot read the row — they are not a member of anything yet — so
-- this reads it for them and returns only what the page needs to say: which
-- organisation, which role, and whether the link is still good. Not who else
-- is invited, and not the token.
--
-- Takes the raw token, so possession of the link is the whole authorisation.
create or replace function public.invitation_preview(p_token text)
returns table (
  organisation_name text,
  role              public.org_role,
  email             text,
  state             text
)
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  hashed text := encode(digest(coalesce(p_token, ''), 'sha256'), 'hex');
  -- Not named `found`: that is PL/pgSQL's own boolean, and shadowing it makes
  -- `if not found` a type error rather than the check it looks like.
  invite record;
begin
  select i.*, o.name as org_name
    into invite
    from public.organisation_invitations i
    join public.organisations o on o.id = i.organisation_id
   where i.token_hash = hashed;

  if invite.id is null then
    -- Deliberately indistinguishable from an expired one on the caller's side:
    -- a separate "no such invitation" would make this a way to test tokens.
    return query select null::text, null::public.org_role, null::text, 'invalid'::text;
    return;
  end if;

  return query select
    invite.org_name::text,
    invite.role,
    invite.email::text,
    case
      when invite.revoked_at is not null then 'revoked'
      when invite.accepted_at is not null then 'accepted'
      when invite.expires_at <= now() then 'expired'
      else 'open'
    end;
end;
$$;

revoke all on function public.invitation_preview(text) from public;
-- anon may call it: someone following an invitation link has usually not
-- signed in yet, and being told what they are being invited to is the point.
grant execute on function public.invitation_preview(text) to anon, authenticated;

-- ── accepting ─────────────────────────────────────────────────────────────
--
-- SECURITY DEFINER because the caller is, by definition, not yet a member of
-- the organisation whose membership row is about to be written — the same
-- reason create_organisation() runs this way.
--
-- The membership is created with the role and scope recorded on the
-- invitation, never with anything the caller sends. There is no parameter here
-- but the token.
create or replace function public.accept_invitation(p_token text)
returns uuid
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  uid        uuid := auth.uid();
  user_email citext;
  invite     public.organisation_invitations;
begin
  if uid is null then
    raise exception 'authentication required' using errcode = '42501';
  end if;

  select u.email into user_email from auth.users u where u.id = uid;

  select * into invite
    from public.organisation_invitations
   where token_hash = encode(digest(coalesce(p_token, ''), 'sha256'), 'hex')
     for update;

  if not found then
    raise exception 'this invitation link is not valid' using errcode = '22023';
  end if;

  if invite.revoked_at is not null then
    raise exception 'this invitation has been withdrawn' using errcode = '22023';
  end if;

  if invite.expires_at <= now() then
    raise exception 'this invitation has expired' using errcode = '22023';
  end if;

  -- Bound to the address it was sent to. Holding the link is not enough:
  -- a forwarded invitation would otherwise hand a stranger access to the
  -- company's data under someone else's name.
  if user_email is null or user_email <> invite.email then
    raise exception 'this invitation was sent to a different email address'
      using errcode = '42501';
  end if;

  -- Already accepted is only an error if somebody else accepted it. For the
  -- same person it is a repeated click, and the answer is where they were
  -- going anyway.
  if invite.accepted_at is not null then
    if invite.accepted_by = uid then
      return invite.organisation_id;
    end if;
    raise exception 'this invitation has already been used' using errcode = '22023';
  end if;

  insert into public.organisation_members
    (organisation_id, user_id, role, status, scope_kind, scope_ids, invited_by, invited_at)
  values
    (invite.organisation_id, uid, invite.role, 'active', invite.scope_kind,
     invite.scope_ids, invite.invited_by, invite.created_at)
  on conflict (organisation_id, user_id) do update
    set status = 'active';

  update public.organisation_invitations
     set accepted_at = now(), accepted_by = uid
   where id = invite.id;

  insert into public.audit_logs
    (organisation_id, actor_id, action, entity_type, entity_id, summary)
  values
    (invite.organisation_id, uid, 'member.joined', 'organisation_member', uid::text,
     invite.email || ' accepted an invitation as ' || invite.role);

  return invite.organisation_id;
end;
$$;

revoke all on function public.accept_invitation(text) from public, anon;
grant execute on function public.accept_invitation(text) to authenticated;

notify pgrst, 'reload schema';

-- ══════════════════════════════════════════════════════════════════════
-- Did it work?
-- ══════════════════════════════════════════════════════════════════════
do $setup$
declare
  tables_found bigint;
  perms_found  bigint;
  grants_found bigint;
begin
  select count(*) into tables_found from pg_tables where schemaname = 'public';
  select count(*) into perms_found  from public.permissions;
  select count(*) into grants_found from public.role_permissions;

  if tables_found <> 46 then
    raise exception 'expected 46 tables, found %', tables_found;
  end if;
  if perms_found <> 30 then
    raise exception 'expected 30 permissions, found %', perms_found;
  end if;
  if grants_found < 100 then
    raise exception 'expected the role matrix to be seeded, found % grants', grants_found;
  end if;

  raise notice 'setup complete: % tables, % permissions, % role grants',
    tables_found, perms_found, grants_found;
end $setup$;

commit;

-- Outside the transaction: PostgREST answers from a cached copy of the
-- schema, and nothing above is visible to the application until it is told.
notify pgrst, 'reload schema';
